#nullable enable
using System.ComponentModel.DataAnnotations.Schema;

namespace Shop;

// Stored as integers (EF Core's default for enums).
public enum OrderState
{
    Pending = 0,
    Paid = 1,
    Shipped = 2,
}

// Stored as text: see HasConversion<string>() in ShopContext.
public enum Tier
{
    Bronze,
    Silver,
    Gold,
}

// No annotations at all: ShopContext.OnModelCreating makes this an owned type of Customer.
public class Address
{
    public string Street { get; set; } = null!;

    public string? City { get; set; }

    public string Zip { get; set; } = null!;
}

public class Customer
{
    // `<TypeName>Id` is a key by convention.
    public int CustomerId { get; set; }

    public string Name { get; set; } = null!;

    public string? Email { get; set; }

    public Tier Tier { get; set; }

    public Address? BillingAddress { get; set; }

    public Address ShippingAddress { get; set; } = new();

    public List<Order> Orders { get; set; } = new();

    [NotMapped]
    public string Scratch { get; set; } = "";

    // Computed in C#: no setter, so EF Core does not map it.
    public string DisplayName => Name;

    // Removed with Ignore() in OnModelCreating.
    public int Internal { get; set; }
}

public class Coupon
{
    public int Id { get; set; }

    public string Code { get; set; } = null!;
}

public class Order
{
    // A Guid key is generated by EF Core on the client.
    public Guid Id { get; set; }

    public OrderState State { get; set; }

    public DateTimeOffset PlacedAt { get; set; }

    public decimal Total { get; set; }

    public int CustomerId { get; set; }

    public Customer Customer { get; set; } = null!;

    // Optional relationship without OnDelete: EF Core's default is ClientSetNull.
    public int? CouponId { get; set; }

    public Coupon? Coupon { get; set; }

    public ICollection<OrderLine> Lines { get; set; } = new HashSet<OrderLine>();

    public byte[]? Version { get; set; }
}

public class OrderLine
{
    public Guid OrderId { get; set; }

    public int LineNo { get; set; }

    public Order Order { get; set; } = null!;

    public int? ProductId { get; set; }

    public Product? Product { get; set; }

    public int Quantity { get; set; }

    public decimal? Discount { get; set; }

    public int DoubleQuantity { get; set; }
}

public class Product
{
    public int Id { get; set; }

    public string Sku { get; set; } = null!;

    public string Name { get; set; } = null!;

    public string? Description { get; set; }

    public double Weight { get; set; }

    public long Stock { get; set; }

    public short Rank { get; set; }

    public bool Active { get; set; }

    public DateOnly? ReleasedOn { get; set; }

    public TimeSpan? ShelfLife { get; set; }

    public Nullable<int> LegacyCode { get; set; }

    public string[] Aliases { get; set; } = Array.Empty<string>();

    public List<Category> Categories { get; set; } = new();
}

public class Category
{
    public int Id { get; set; }

    public string Title { get; set; } = null!;

    public List<Product> Products { get; set; } = new();
}
